-- Rollback de 20260930140600_voz_agente_pedro_guion_prospeccion.sql
--
-- Devuelve al agente «Pedro, asistente comercial» (org 125) el texto EXACTO que
-- tenía antes (encuesta de satisfacción). Los textos van en base64 para
-- conservarlos byte a byte (comillas tipográficas y saltos de línea); se
-- comprueba el md5 de cada uno contra el que tenía la base el 2026-09-30:
--   system_prompt       d8f7d668744f49c7c4f55d1240c7caad
--   first_message       ed237aa35be4c4e71e475c4c65de4c31
--   identity_disclosure 38e2b2e31c0fce9537f735dda9fdf10a

do $$
declare
  v_sp text := convert_from(decode('', 'base64'), 'UTF8');
  v_fm text := convert_from(decode('SG9sYSwgc295IFBlZHJvLCBlbCBhc2lzdGVudGUgZGUgaW50ZWxpZ2VuY2lhIGFydGlmaWNpYWwgZGUge3tvcmd9fS4gRXN0YW1vcyBwcm9iYW5kbyBudWVzdHJvIG51ZXZvIGFzaXN0ZW50ZSB0ZWxlZsOzbmljbyB5IG5vcyBndXN0YXLDrWEgY29ub2NlciB0dSBleHBlcmllbmNpYSBjb24gbGEgcGxhdGFmb3JtYS4gwr9UaWVuZXMgZG9zIG1pbnV0b3MgcGFyYSBwYXJ0aWNpcGFyPw==', 'base64'), 'UTF8');
  v_id text := convert_from(decode('UGVkcm8=', 'base64'), 'UTF8');
  v_n integer;
begin
  if md5(v_sp) <> 'd8f7d668744f49c7c4f55d1240c7caad'
     or md5(v_fm) <> 'ed237aa35be4c4e71e475c4c65de4c31'
     or md5(v_id) <> '38e2b2e31c0fce9537f735dda9fdf10a' then
    raise exception 'Los textos del rollback no coinciden con los originales (md5)';
  end if;

  update public.voice_agents
     set system_prompt = v_sp,
         first_message = v_fm,
         identity_disclosure = v_id,
         updated_at = now()
   where organization_id = 125 and name = 'Pedro, asistente comercial';
  get diagnostics v_n = row_count;
  if v_n <> 1 then
    raise exception 'Se esperaba revertir exactamente un agente y se revirtieron %', v_n;
  end if;
end $$;
